8	/**
9	 * Build a pre-filled Nxeon wizard URL for a linked user to complete a purchase.
10	 * Kodely redirects the user's BROWSER to the returned `url`; the SSO handshake has
11	 * already given them an Nxeon session, so they land straight in the wizard with the
12	 * shared wallet + Stripe + provisioner behind it (no money-path reimplemented).
13	 *
14	 * Body: { userId, product: "domain" | "vps" | "hosting", domain?: string }
15	 */
16	export async function POST(req: Request) {
17	  if (!(await isPartnerRequest(req))) return Response.json({ error: "unauthorized" }, { status: 401 });
18	  let body: { userId?: string; product?: string; domain?: string };
19	  try {
20	    body = await req.json();
21	  } catch {
22	    return Response.json({ error: "invalid json" }, { status: 400 });
23	  }
24	  if (!body.userId) return Response.json({ error: "userId required" }, { status: 400 });
25	  const user = await db.user.findUnique({ where: { id: body.userId }, select: { id: true } });
26	  if (!user) return Response.json({ error: "user not found" }, { status: 404 });
27	
28	  let path: string;
29	  switch (body.product) {
30	    case "domain": {
31	      const d = typeof body.domain === "string" && /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(body.domain) ? body.domain : "";
32	      path = d ? `/dashboard/domains?q=${encodeURIComponent(d)}&ref=kodely` : `/dashboard/domains?ref=kodely`;
33	      break;
34	    }
35	    case "vps":
36	      path = `/dashboard/deploy?product=vps&ref=kodely`;
37	      break;
38	    case "hosting":
39	      // NOT /dashboard/order — that route is a dumb redirect to the VPS wizard
40	      // regardless of any query param (verified 2026-08-22). The real hosting
41	      // order flow lives on the unified Deploy hub.
42	      path = `/dashboard/deploy?product=hosting&ref=kodely`;
43	      break;
44	    default:
45	      return Response.json({ error: "product must be domain | vps | hosting" }, { status: 400 });
46	  }
47	  return Response.json({ url: `${APP_URL}${path}` });
