22	/**
23	 * Front door to the Nxeon live-chat AGENT.
24	 *
25	 * The assistant is a Claude-powered agent (lib/kb-llm.ts) that reasons over the
26	 * full operator knowledge base and a suite of live tools — account lookups for
27	 * signed-in customers, plus public tools for plans, platform status, and help
28	 * search — and answers in its own words. There is NO keyword-retrieval fallback
29	 * that pastes blog snippets: retrieval only ever SEEDS the agent as context.
30	 *
31	 * When the model is genuinely unavailable (no key configured, or an API error)
32	 * the bot degrades GRACEFULLY to one warm, honest message that offers a human
33	 * follow-up — it never dumps an article link as "the answer". The failure reason
34	 * rides back on the result so the orchestrator (lib/kb-run.ts) can log a real
35	 * degradation for the operator instead of failing silently.
36	 *
37	 * Every call returns a typed `kind` so app/api/chat/route.ts can log it.
38	 * The index (KbChunk) is (re)built by lib/actions-kb.ts → reindexKb().
39	 */
40	
41	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
42	
43	export type ReplyKind = "smalltalk" | "handoff" | "offer" | "answer" | "degraded";
44	export type KbResult = {
45	  kind: ReplyKind;
46	  reply: string | null;
47	  matchedTitle?: string;
48	  /** Plan-card keys to render with this reply (resolved to cards in kb-run). */
49	  cardKeys?: string[];
50	  /** Present only when the model was unavailable, so the orchestrator can log a
51	   *  real degradation and alert the operator on a hard error (never silent). */
52	  llmFailure?: "no_key" | "error" | "over_cap";
53	};
54	
55	/** Warm, honest degradation — used ONLY when the model can't run (no key / API
56	 *  error / over the daily cap). Never a blog link; offers a human follow-up.
57	 *  Exported so the graceful-degradation contract (offers contact/pricing, never
58	 *  a blog link) can be asserted in a hermetic unit test. */
59	export function degradedReply(reason: "no_key" | "error" | "over_cap", name?: string | null): string {
60	  const who = name && name.trim() ? ` ${name.trim()}` : "";
61	  if (reason === "over_cap") {
62	    return `Thanks${who} — we're helping a lot of people in chat right now, so rather than rush you I want to make sure you get a solid answer. Drop your email with your question and the team will get right back to you (usually within a business day). In the meantime, ${APP_URL}/pricing has every plan and ${APP_URL}/help has quick guides.`;
63	  }
64	  return `Sorry${who} — I'm having a brief problem reaching my assistant just now. I don't want to guess at your answer. If you leave your email and what you need, the team will follow up quickly — or you can reach us any time at ${APP_URL}/contact. You can also check live status at ${APP_URL}/status.`;
65	}
66	
67	/** "which plan / what plan / recommend a plan / best plan / plan for X". */
68	export function planIntent(text: string): boolean {
69	  return /\b(which|what|best)\s+plan\b|\bplan\s+(should|would|do|for|to)\b|\brecommend\s+(a\s+)?plan\b|\bhelp me (choose|pick)\b|\bwhich (one|option|tier)\b/i.test(
70	    text,
71	  );
72	}
73	
74	type Row = { source: string; title: string; url: string | null; snippet: string; offer: boolean; rank: number };
75	
76	/** Explicit "get me a person". */
77	export function humanIntent(text: string): boolean {
78	  return /\b(human(?:\s+(?:being|agent))?|agent|operator|representative|rep|customer\s+(?:service|support|rep)|real\s+(?:person|human)|actual\s+(?:person|human)|live\s+(?:chat|agent|support|person)|someone|a person|talk to (?:a|your|the|someone)|speak (?:to|with)|connect me|get me (?:a|someone))\b/i.test(text);
79	}
80	
81	/** "Do you have any deals / discounts / promos?" */
82	export function offerIntent(text: string): boolean {
83	  return /\b(deal|deals|discount|discounts|promo|promotion|coupon|voucher|offer|offers|sale|cheaper|save (money|some)|free month|free trial|any specials?)\b/i.test(text);
84	}
85	
86	/** Top knowledge-base matches. websearch_to_tsquery parses arbitrary user input
87	 *  safely, so this is injection- and crash-safe for anything a visitor types. */
88	export async function kbSearch(query: string, limit = 4): Promise<Row[]> {
89	  const q = query.trim();
90	  if (q.length < 3) return [];
91	  try {
92	    return await db.$queryRaw<Row[]>`
93	      SELECT source, title, url, snippet, "offer",
94	             ts_rank(to_tsvector('english', title || ' ' || content),
95	                     websearch_to_tsquery('english', ${q})) AS rank
96	      FROM "KbChunk"
97	      WHERE to_tsvector('english', title || ' ' || content) @@ websearch_to_tsquery('english', ${q})
98	      ORDER BY rank DESC
99	      LIMIT ${limit}`;
100	  } catch {
101	    return [];
102	  }
103	}
104	
105	/**
106	 * Decide how the assistant should respond to a visitor message. Priority:
107	 * explicit human hand-off → the Claude agent (tools + full KB, for everyone) →
108	 * graceful degradation if the model can't run. There is no keyword-retrieval
109	 * fallback and no canned "clarifier" — the agent handles greetings, questions,
110	 * and everything in between. Always returns a `kind` so the caller can log
111	 * coverage. `history` is the prior conversation (oldest→newest) for context.
112	 */
113	export async function kbAnswer(message: string, opts: KbAnswerOpts = {}): Promise<KbResult> {
114	  const history = opts.history ?? [];
115	
116	  // 1. Explicit "get me a person" — hand-off (kb-run turns this into the live
117	  //    escalation + email flow). No tokens spent.
118	  if (humanIntent(message)) {
119	    return {
120	      kind: "handoff",
121	      reply:
122	        "No problem — I'll connect you with our team. Someone will be with you shortly. Feel free to add any details in the meantime.",
123	    };
124	  }
125	
126	  // 2. Over the daily cost cap → degrade gracefully (no model call, no snippet).
127	  if (opts.noLlm) {
128	    return {
129	      kind: "degraded",
130	      reply: degradedReply("over_cap", opts.visitorName),
131	      llmFailure: "over_cap",
132	    };
133	  }
134	
135	  // 3. Seed a little help context (cheap FTS), then run the agent for EVERYONE.
136	  //    The agent investigates with its tools and answers in its own words; plan
137	  //    cards ride back via a hidden [[cards: …]] directive parsed in kb-run.
138	  const rows = await kbSearch(message);
139	  const chunks = rows.map((r) => ({ title: r.title, snippet: r.snippet, url: r.url }));
140	  const res = await llmAnswer({
141	    message,
142	    history,
143	    chunks,
144	    images: opts.images,
145	    visitorName: opts.visitorName ?? null,
146	    userId: opts.userId ?? null,
147	    conversationId: opts.conversationId ?? null,
148	  });
149	
150	  if (res.ok) {
151	    return {
152	      kind: offerIntent(message) ? "offer" : "answer",
153	      reply: res.text,
154	      matchedTitle: rows[0]?.title,
155	    };
156	  }
157	
158	  // 4. Model unavailable. NEVER paste a blog snippet. A plain greeting still gets
159	  //    a warm hello; anything else gets an honest "let me get the team" message.
160	  //    The failure reason rides back so kb-run logs a real degradation.
161	  if (res.reason === "no_key" && greetingIntent(message)) {
162	    return { kind: "smalltalk", reply: greetingReply(opts.visitorName) };
163	  }
164	  return {
165	    kind: "degraded",
166	    reply: degradedReply(res.reason === "error" ? "error" : "no_key", opts.visitorName),
167	    llmFailure: res.reason === "error" ? "error" : "no_key",
168	  };
169	}
